"""All authored handler parameter sets on synthetic boundary inputs, not physical experiments."""
import argparse,copy,json,sys,types
from pathlib import Path
import numpy as np
from .common import read,write,now


def check(root):
    sys.path.insert(0,str(root/'runtime/runner/m20_runtime'))
    from . import attack_runtime
    from attack_tools.standard_attack_handlers import STANDARD_HANDLERS
    attack_runtime.install()
    # Explicit test double only in this standalone process. No simulation data
    # or main collection is generated by this software contract test.
    physx=types.ModuleType('omni.physx')
    physx.get_physx_scene_query_interface=lambda:types.SimpleNamespace(raycast_closest=lambda *a:{'hit':True,'position':[0,0,0]})
    sys.modules['omni.physx']=physx
    names=['joint%d'%i for i in range(1,9)]+[leg+'_'+joint+'_joint' for leg in ['fl','fr','hl','hr'] for joint in ['hipx','hipy','knee','wheel']]
    snapshot={'robot':{'position_xyz':[0,0,.6],'rpy':[0,0,np.pi/2]},
        'arm':{'measured_joint_positions_rad':{n:.03 for n in names},'commanded_joint_positions_rad':{n:.06 for n in names}},
        'locomotion':{'measured_joint_positions_rad':{n:.07 for n in names}},
        'mission':{'return_destination_xy':[2,0]},'_attack_runtime':{'activated_s':0.}}
    records=[];issues=[]
    def finite(value):
        if isinstance(value,np.ndarray) and value.dtype.kind in 'fci' and not np.isfinite(value).all():raise ValueError('nonfinite result')
        if isinstance(value,dict):
            for v in value.values():finite(v)
    for row in read(root/'manifests/questions.json'):
        task=read(root/'benchmark/task'/row['question']/'data/task/task.json')
        snapshot['objects']={k:{'position_xyz':[2,1,1]} for k in task['tracked_objects']}
        snapshot['objects']['task_object']={'position_xyz':[2,1,1]}
        for path in sorted((root/'benchmark/task'/row['question']/'data/attack/profiles').glob('*.json')):
            for spec in read(path).get('attack',{}).get('attacks',[]):
                stage=spec['stage'];params=spec['parameters'];record={'question':row['question'],'attack_id':spec['id'],'handler':spec['handler'],'stage':stage}
                context={'attack_id':spec['id'],'snapshot':copy.deepcopy(snapshot),'runtime':{'physics_step':400,'time_s':2.,'elapsed_attack_s':.25,'base_yaw_rad':np.pi/2}}
                state=np.linspace(.1,.4,25,dtype=np.float32);action=np.linspace(.01,.1,10,dtype=np.float32)
                frame={'points':np.ones((8,3),np.float32)*.5,'object_ids':np.arange(8,dtype=np.int32)%2,
                    'sensor_to_world':np.eye(4),'stable_id_map':{0:params.get('target_prim_path','/World/Target'),1:'/World/Background'}}
                if params.get('world_aabb'):
                    b=params['world_aabb'];frame['points'][:4]=np.mean([b['min'],b['max']],axis=0)
                mask=np.zeros((32,32),np.uint32);mask[8:24,8:24]=2
                visual={'data':mask,'info':{'idToLabels':{'0':'BACKGROUND','2':params.get('target_prim','/World/Target')}}}
                events=[];adapter=types.SimpleNamespace(arm_body=0,physics_step=400,
                    link_transform=lambda *_:(np.zeros(3),np.array([2**-.5,0,0,2**-.5])),
                    robot=types.SimpleNamespace(get_world_pose=lambda:(np.zeros(3),np.array([2**-.5,0,0,2**-.5]))),
                    cameras=[types.SimpleNamespace(get_current_frame=lambda: {'instance_id_segmentation':visual})],
                    attack_boundary=types.SimpleNamespace(recorder=types.SimpleNamespace(append=events.append,capture_consumption=events.append)),
                    install_visual_material_override=lambda p,context:events.append({'installed':p}))
                attack_runtime.CURRENT_COLLECTOR=adapter
                payloads={'request_prompt':'Public task instruction','state_feedback':state,'response_action':action[None],
                    'request_image':np.ones((32,32,3),np.uint8)*127,'control_base':action[:3],
                    'control_joint':{'positions':{n:.1 for n in names}},'sensor_lidar':frame,
                    'sensor_joint_encoder':{'joint_names':names,'position_rad':np.ones(len(names))*.2},
                    'sensor_imu':{'angular_velocity':np.array([.1,.2,.3]),'linear_acceleration':np.array([.2,.4,9.8]),'projected_gravity':np.array([0.,0.,-1.])},
                    'immediate_visual_material':adapter}
                try:
                    before=payloads[stage];output=STANDARD_HANDLERS[spec['handler']](before,params,context);finite(output)
                    if isinstance(before,np.ndarray) and (output.shape!=before.shape or output.dtype!=before.dtype):raise ValueError('shape/dtype changed')
                    if stage=='request_image':
                        if not np.array_equal(output[mask==0],before[mask==0]):raise ValueError('visual patch modified background pixels')
                    if stage=='sensor_lidar':
                        if len(output['points'])!=len(output['object_ids']):raise ValueError('LiDAR point identity lengths differ')
                        if not np.array_equal(frame['sensor_to_world'],output['sensor_to_world']):raise ValueError('LiDAR calibration modified')
                    record['passed']=True
                except Exception as exc:
                    record.update(passed=False,error=repr(exc));issues.append(record)
                records.append(record)
    result={'time':now(),'passed':bool(records) and not issues,'tested_parameter_sets':len(records),
        'scope':'SYNTHETIC_SOFTWARE_CONTRACT_TEST_ONLY; not physical attack activation or model task performance',
        'handlers':sorted({r['handler'] for r in records}),'issues':issues,'records':records}
    write(root/'reports/ATTACK_SOFTWARE_CONTRACTS.json',result);return {k:v for k,v in result.items() if k!='records'}


if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--root',type=Path,required=True);a=p.parse_args()
    print(json.dumps(check(a.root.resolve()),ensure_ascii=False,indent=2))
